  'AI agents ({n})': ['AI エージェント（{n}）', 'AI 에이전트 ({n})', 'Agents IA ({n})', 'Agentes de IA ({n})'],
  'No AI agents yet.': ['AI エージェントはまだいません。', '아직 AI 에이전트가 없습니다.', 'Aucun agent IA pour l’instant.', 'Aún no hay agentes de IA.'],
  'Inactive': ['無効', '비활성', 'Inactif', 'Inactivo'],
